const PAYLOAD = [{"id":"pnj-grands-exiles-gaston-zarmel-43","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Gaston Zarmel","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Ligue des Quatre Empereurs","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Gaston Zarmel","real_name_source":"Gaston Zarmel","nom_verite":"Gharza","nom_verite_source":"Gharza","race":"Gobeline (ashylle)","age":"« 40 ans»","origine":"américaine","statut":"","affiliations":"Corporations : Nextar","source_group":"Ligue des Quatre Empereurs","source_groups":["Ligue des Quatre Empereurs"],"source_pages":[34],"source_occurrences":1,"source_order":2,"identity_keys":["Gaston Zarmel","Gharza","siège impérial : Gharza"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"siège impérial : Gharza Nom de la Réalité : Gaston Zarmel Nom de la Vérité : Gharza Age : « 40 ans» Affiliations : Corporations : Nextar Nationalité d’origine : américaine Ethnie réelle : Gobeline (ashylle) Titre dans la faction : Empereur Gaston Zarmel est le plus grand présentateur humoristique des chaines de Nextar media. Autant Lys a le cœur de tous les spectateurs, autant Gaston amuse autant de gens qu’il n’en dégoute. Il n’a aucun respect, pour personne, hormis Gabriella et Wei, ses patronnes. Il est le roi de l’humour en Californie, acteurs, humoristes, présentateurs, holotubeurs, tous ont plus ou moins intérêt à courber l’échine. Gharza est un empereur gobelin, à voir son apparence humaine, on ne le dirait pas, une fois révélé, il rétrécie beaucoup, étant le plus petit des empereurs physiquement. C’est un tribun, un orateur de génie, Atreesha adore l’envoyer tenir la jambe de membres du conseil, même sans avoir fait de droit, c’est un génie des plaidoyers. Atreesha l’a créé, elle n’est pas sa mère, mais a magiquement fertilisé une héritière renégate d’une lignée un peu trop hostile. Il est immortel mais c’est là sa seule vraie qualité magique. Quand le conseil des Anciens veut gagner du temps auprès de la Chasse Fantastique, il envoie Gharza papoter avec l’’indomptable Titania."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Gaston Zarmel"],["Âge apparent","40 ans"],["Nationalité déclarée","américaine"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","siège impérial : Gharza"],["Nom de la Réalité","Gaston Zarmel"],["Nom de la Vérité","Gharza"],["Âge source","« 40 ans»"],["Affiliations","Corporations : Nextar"],["Nationalité d’origine","américaine"],["Nature réelle","Gobeline (ashylle)"]]},{"type":"p","style":"lore","text":"Titre dans la faction : Empereur Gaston Zarmel est le plus grand présentateur humoristique des chaines de Nextar media. Autant Lys a le cœur de tous les spectateurs, autant Gaston amuse autant de gens qu’il n’en dégoute. Il n’a aucun respect, pour personne, hormis Gabriella et Wei, ses patronnes. Il est le roi de l’humour en Californie, acteurs, humoristes, présentateurs, holotubeurs, tous ont plus ou moins intérêt à courber l’échine. Gharza est un empereur gobelin, à voir son apparence humaine, on ne le dirait pas, une fois révélé, il rétrécie beaucoup, étant le plus petit des empereurs physiquement. C’est un tribun, un orateur de génie, Atreesha adore l’envoyer tenir la jambe de membres du conseil, même sans avoir fait de droit, c’est un génie des plaidoyers. Atreesha l’a créé, elle n’est pas sa mère, mais a magiquement fertilisé une héritière renégate d’une lignée un peu trop hostile. Il est immortel mais c’est là sa seule vraie qualité magique. Quand le conseil des Anciens veut gagner du temps auprès de la Chasse Fantastique, il envoie Gharza papoter avec l’’indomptable Titania."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-sa-rang-sung-44","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Sa-Rang SUNG","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Ligue des Quatre Empereurs","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Sa-Rang SUNG","real_name_source":"Sa-Rang SUNG","nom_verite":"Teezdia","nom_verite_source":"Teezdia","race":"Gobeline (ashylle)","age":"« ??? »","origine":"Coréenne","statut":"","affiliations":"Corporations : Wellspring","source_group":"Ligue des Quatre Empereurs","source_groups":["Ligue des Quatre Empereurs"],"source_pages":[35],"source_occurrences":1,"source_order":1,"identity_keys":["Sa-Rang SUNG","Teezdia","siège impérial : Teezdia"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"siège impérial : Teezdia Nom de la Réalité : Sa-Rang SUNG Nom de la Vérité : Teezdia Age : « ??? » Affiliations : Corporations : Wellspring Nationalité d’origine : Coréenne Ethnie réelle : Gobeline (ashylle) Titre dans la faction : Impératrice Sa-rang est la directrice des branches liées aux énergies combustibles, une branche vouée à disparaitre qui se cherche une place en 2035, se renouvelant et se révolutionnant le plus possible. Sa-rang est loin d’être une directrice de branche calme et posée, c’est une femme qui cache une facette très agressive et audacieuse, le pétrole et autres énergies fossiles ont beau ne plus servir autant, ces matières restent la base de gros enjeux et elle est du genre à mener des guerres sanguinaires pour protéger ou obtenir des filons. Impératrice gobeline, Teezdia assume pleinement son nom qui évoque celui d’une ancienne déesse gobeline de la mort. C’est le bras armé de la ligue, elle est la plus prompte à engager des mercenaires pour combattre le syndicat de Jade. Elle a un profond mépris pour les protégés du Conseil des Anciens. Malgré une intelligence dangereuse et une vivacité d’esprit rare, elle a un grave manque de reconnaissance et de figure maternelle, Atreesha ne l’a pas choisi pour rien, comblant ce besoin et cette recherche de reconnaissance pour s’assurer sa loyauté totale."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Sa-Rang SUNG"],["Âge apparent","???"],["Nationalité déclarée","Coréenne"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","siège impérial : Teezdia"],["Nom de la Réalité","Sa-Rang SUNG"],["Nom de la Vérité","Teezdia"],["Âge source","« ??? »"],["Affiliations","Corporations : Wellspring"],["Nationalité d’origine","Coréenne"],["Nature réelle","Gobeline (ashylle)"]]},{"type":"p","style":"lore","text":"Titre dans la faction : Impératrice Sa-rang est la directrice des branches liées aux énergies combustibles, une branche vouée à disparaitre qui se cherche une place en 2035, se renouvelant et se révolutionnant le plus possible. Sa-rang est loin d’être une directrice de branche calme et posée, c’est une femme qui cache une facette très agressive et audacieuse, le pétrole et autres énergies fossiles ont beau ne plus servir autant, ces matières restent la base de gros enjeux et elle est du genre à mener des guerres sanguinaires pour protéger ou obtenir des filons. Impératrice gobeline, Teezdia assume pleinement son nom qui évoque celui d’une ancienne déesse gobeline de la mort. C’est le bras armé de la ligue, elle est la plus prompte à engager des mercenaires pour combattre le syndicat de Jade. Elle a un profond mépris pour les protégés du Conseil des Anciens. Malgré une intelligence dangereuse et une vivacité d’esprit rare, elle a un grave manque de reconnaissance et de figure maternelle, Atreesha ne l’a pas choisi pour rien, comblant ce besoin et cette recherche de reconnaissance pour s’assurer sa loyauté totale."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-risham-al-marid-45","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Risham Al’Marid","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Ligue des Quatre Empereurs","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Risham Al’Marid","real_name_source":"Risham Al’Marid","nom_verite":"Reezma","nom_verite_source":"Reezma","race":"Gobeline (Ashylle)","age":"« 40» - ???? ans","origine":"Marocaine","statut":"","affiliations":"Religieux : Islam","source_group":"Ligue des Quatre Empereurs","source_groups":["Ligue des Quatre Empereurs"],"source_pages":[35],"source_occurrences":1,"source_order":2,"identity_keys":["Risham Al’Marid","Reezma","siège impérial : Reezma"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"siège impérial : Reezma Nom de la Réalité : Risham Al’Marid Nom de la Vérité : Reezma Age : « 40» - ???? ans Affiliations : Religieux : Islam Nationalité d’origine : Marocaine Ethnie réelle : Gobeline (Ashylle) Titre dans la faction : Empereur Risham est un Imam mais aussi un chasseur religieux, il est capable d’invoquer La véritable ‘al’Battar », l’épée de Goliath détenue par le Prophète. C’est une épée de dive en vérité, fortement enchantée et réenchantée par la religion Musulmane. C’est littéralement une épée qui force les Mageius à passer dans le domaine de la lumière, le plus difficile pour les dives. Il est entêté et impitoyable mais ce n’est pas le plus moderniste des Imams. Derrière l’homme de foi se cache un grand empereur Gobelin, le conquérant Reezma. De conquérant, il n’en a néanmoins que le nom, n’étant pas si vieux que ça, il n’a jamais rien accompli dans ce registre. Même s’il a une forte image de combattant, d’homme de terrain, Reezma est un législateur en vérité, il a l’allure d’un type dur et badass mais c’est un diplomate, le genre à sortir son flingue essentiellement pour discuter, et malgré la possession d’une relique religieuse, il chasse essentiellement en discutant avec ses proies, c’est un négociateur qui tue rarement. Atreesha l’a bien formé, il exploite les dons religieux des Cieux, s’allie avec les Ombres et les revenants, les orcs et les exilés. La seule fois où il va tirer sans discuter c’est face à un cadre du syndicat. Même avec les Mages il négocie, souvent pour les piéger."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Risham Al’Marid"],["Âge apparent","40"],["Nationalité déclarée","Marocaine"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","siège impérial : Reezma"],["Nom de la Réalité","Risham Al’Marid"],["Nom de la Vérité","Reezma"],["Âge source","« 40» - ???? ans"],["Affiliations","Religieux : Islam"],["Nationalité d’origine","Marocaine"],["Nature réelle","Gobeline (Ashylle)"]]},{"type":"p","style":"lore","text":"Titre dans la faction : Empereur Risham est un Imam mais aussi un chasseur religieux, il est capable d’invoquer La véritable ‘al’Battar », l’épée de Goliath détenue par le Prophète. C’est une épée de dive en vérité, fortement enchantée et réenchantée par la religion Musulmane. C’est littéralement une épée qui force les Mageius à passer dans le domaine de la lumière, le plus difficile pour les dives. Il est entêté et impitoyable mais ce n’est pas le plus moderniste des Imams. Derrière l’homme de foi se cache un grand empereur Gobelin, le conquérant Reezma. De conquérant, il n’en a néanmoins que le nom, n’étant pas si vieux que ça, il n’a jamais rien accompli dans ce registre. Même s’il a une forte image de combattant, d’homme de terrain, Reezma est un législateur en vérité, il a l’allure d’un type dur et badass mais c’est un diplomate, le genre à sortir son flingue essentiellement pour discuter, et malgré la possession d’une relique religieuse, il chasse essentiellement en discutant avec ses proies, c’est un négociateur qui tue rarement. Atreesha l’a bien formé, il exploite les dons religieux des Cieux, s’allie avec les Ombres et les revenants, les orcs et les exilés. La seule fois où il va tirer sans discuter c’est face à un cadre du syndicat. Même avec les Mages il négocie, souvent pour les piéger."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-norlan-damon-46","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Norlan Damon","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Cercle Écarlate","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Norlan Damon","real_name_source":"Norlan Damon","nom_verite":"Nor’draar","nom_verite_source":"Nor’draar","race":"Astharès","age":"« 49 ans »","origine":"Américaine","statut":"","affiliations":"Corporatif : Redwheels/tuatha – crawlers : fixers","source_group":"Cercle Écarlate","source_groups":["Cercle Écarlate"],"source_pages":[38],"source_occurrences":1,"source_order":1,"identity_keys":["Norlan Damon","Nor’draar","Nor fondateur : Nordrar"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Nor fondateur : Nordrar Nom de la Réalité : Norlan Damon Nom de la Vérité : Nor’draar Age : « 49 ans » Affiliations : Corporatif : Redwheels/tuatha – crawlers : fixers Nationalité d’origine : Américaine Ethnie réelle : Astharès Rang dans le cercle : Divinité suprême Norlan Damon est un fixer de Los angeles, ce n’est pas le plus actif ni le plus rentable, mais c’est un des plus bienveillants, quand on est engagé deux fois par lui, c’est qu’il respecte les crawlers assez pour les protéger, un cas très rare. Toutefois, l’essentiel de sa vie se passe en tant qu’acteur porno où ses proportions inhumaines et son endurance monstrueuse en font une source fiable de revenue pour tous les studios. Autrefois, il était de la Black Raven c’était même un des plus grands officiers de Morrighan puis Katja jusqu’à la guerre de 22-28. Lassé des combats, il cherche à aider et protéger les gens, même s’il reste une bête inattaquable, ce n’est pas un type agressif, en revanche, mieux vaut avoir des ovaires, car il considère assez peu le cas des mâles en général. Dans la vérité, c’est un Dieu du Chaos et de la domination du monde de Gaerras seconde, après avoir ravagé Gaerras première et été enfermé une grande partie de sion existence, il vint sur Terre pour avoir une repentance. C’est un ami de Belial et de Katja mais aussi de Morrighan. Il craint le cercle écarlate, car il sent qu’u jour, cette secte va causer de gros dégâts en essayant de créer un nouveau dieu."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Norlan Damon"],["Âge apparent","49 ans"],["Nationalité déclarée","Américaine"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Nor fondateur : Nordrar"],["Nom de la Réalité","Norlan Damon"],["Nom de la Vérité","Nor’draar"],["Âge source","« 49 ans »"],["Affiliations","Corporatif : Redwheels/tuatha – crawlers : fixers"],["Nationalité d’origine","Américaine"],["Nature réelle","Astharès"]]},{"type":"p","style":"lore","text":"Rang dans le cercle : Divinité suprême Norlan Damon est un fixer de Los angeles, ce n’est pas le plus actif ni le plus rentable, mais c’est un des plus bienveillants, quand on est engagé deux fois par lui, c’est qu’il respecte les crawlers assez pour les protéger, un cas très rare. Toutefois, l’essentiel de sa vie se passe en tant qu’acteur porno où ses proportions inhumaines et son endurance monstrueuse en font une source fiable de revenue pour tous les studios. Autrefois, il était de la Black Raven c’était même un des plus grands officiers de Morrighan puis Katja jusqu’à la guerre de 22-28. Lassé des combats, il cherche à aider et protéger les gens, même s’il reste une bête inattaquable, ce n’est pas un type agressif, en revanche, mieux vaut avoir des ovaires, car il considère assez peu le cas des mâles en général. Dans la vérité, c’est un Dieu du Chaos et de la domination du monde de Gaerras seconde, après avoir ravagé Gaerras première et été enfermé une grande partie de sion existence, il vint sur Terre pour avoir une repentance. C’est un ami de Belial et de Katja mais aussi de Morrighan. Il craint le cercle écarlate, car il sent qu’u jour, cette secte va causer de gros dégâts en essayant de créer un nouveau dieu."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-ken-ferno-47","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Ken Ferno","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Cercle Écarlate","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Ken Ferno","real_name_source":"Ken Ferno","nom_verite":"Kai’nor / Caïn","nom_verite_source":"Kai’nor / Caïn","race":"Astharès/ Dieux anciens","age":"« 30 ans »","origine":"Américano-iranienne","statut":"","affiliations":"crawlers : mercs","source_group":"Cercle Écarlate","source_groups":["Cercle Écarlate"],"source_pages":[38],"source_occurrences":1,"source_order":2,"identity_keys":["Ken Ferno","Kai’nor / Caïn","Kai’nor","Caïn","Nor vénéré : Kainor"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Nor vénéré : Kainor Nom de la Réalité : Ken Ferno Nom de la Vérité : Kai’nor / Caïn Age : « 30 ans » Affiliations : crawlers : mercs Nationalité d’origine : Américano-iranienne Ethnie réelle : Astharès/ Dieux anciens Rang dans le cercle : Divinité sacrée mais scellée Kain Ferno est un soldat de l’US. Navy à l’origine, et, jusqu’à l’arrivée de Catalina dans les rangs des Seals, il était le meilleur de tous les Navy seals tout simplement. Il a été l’officier de l’espagnole, avant qu’elle ne le surpasse en grade, il a fini par devenir un officier supérieur néanmoins, par son héroïsme mais en 2035, il enchaine dépressions et pertes de repères dans la société trop changeantes pour lui, on le croise essentiellement pour des boulots de mercenaires ou à picoler au Purple Embers. Fil de la reine Belial et de Nordrar, il aurait pu être un des dieux les plus grands et glorieux, mais sa vie n’a été qu’une suite d’échecs, de désastre et de mauvaises décisions. Il a clairement un complexe d’Œdipe, qui ne va pas en vieillissant d’une part, d’autre part, il est vraiment malchanceux. Sa première amie était Elynea, on ignore si elle se servit de lui ou eut une vraie amitié pour lui, mais à sa rébellion, elle le plaça dans une sale situation. La troisième femme dans sa vie, décisive, est R’Gahanath, qui, assurément, l’utilisa pour améliorer les vampires par la marque de Cain. Il est scellé et sans grande ambition, n’attendant rien de la vie, ayant l’impression qu’il a déjà grillé toutes ses opportunités d’accomplir quelque chose."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Ken Ferno"],["Âge apparent","30 ans"],["Nationalité déclarée","Américano-iranienne"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Nor vénéré : Kainor"],["Nom de la Réalité","Ken Ferno"],["Nom de la Vérité","Kai’nor / Caïn"],["Âge source","« 30 ans »"],["Affiliations","crawlers : mercs"],["Nationalité d’origine","Américano-iranienne"],["Nature réelle","Astharès/ Dieux anciens"]]},{"type":"p","style":"lore","text":"Rang dans le cercle : Divinité sacrée mais scellée Kain Ferno est un soldat de l’US. Navy à l’origine, et, jusqu’à l’arrivée de Catalina dans les rangs des Seals, il était le meilleur de tous les Navy seals tout simplement. Il a été l’officier de l’espagnole, avant qu’elle ne le surpasse en grade, il a fini par devenir un officier supérieur néanmoins, par son héroïsme mais en 2035, il enchaine dépressions et pertes de repères dans la société trop changeantes pour lui, on le croise essentiellement pour des boulots de mercenaires ou à picoler au Purple Embers. Fil de la reine Belial et de Nordrar, il aurait pu être un des dieux les plus grands et glorieux, mais sa vie n’a été qu’une suite d’échecs, de désastre et de mauvaises décisions. Il a clairement un complexe d’Œdipe, qui ne va pas en vieillissant d’une part, d’autre part, il est vraiment malchanceux. Sa première amie était Elynea, on ignore si elle se servit de lui ou eut une vraie amitié pour lui, mais à sa rébellion, elle le plaça dans une sale situation. La troisième femme dans sa vie, décisive, est R’Gahanath, qui, assurément, l’utilisa pour améliorer les vampires par la marque de Cain. Il est scellé et sans grande ambition, n’attendant rien de la vie, ayant l’impression qu’il a déjà grillé toutes ses opportunités d’accomplir quelque chose."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-eliza-freyja-48","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Eliza Freyja","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Cercle Écarlate","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Eliza Freyja","real_name_source":"Eliza Freyja","nom_verite":"E’nor’rea","nom_verite_source":"E’nor’rea","race":"Astharès","age":"« 24 ans »","origine":"Américaine","statut":"","affiliations":"crawlers : neopunks","source_group":"Cercle Écarlate","source_groups":["Cercle Écarlate"],"source_pages":[39],"source_occurrences":1,"source_order":1,"identity_keys":["Eliza Freyja","E’nor’rea","Nor vénéré : Enorea"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Nor vénéré : Enorea Nom de la Réalité : Eliza Freyja Nom de la Vérité : E’nor’rea Age : « 24 ans » Affiliations : crawlers : neopunks Nationalité d’origine : Américaine Ethnie réelle : Astharès Rang dans le cercle : Divinité sacrée mais introuvable Eliza est une neopunk qui n’assure pas sa notoriété par un coté destructeur ou antisocial, elle est une neopunk qui vante les qualités et l’égalité de tous les êtres, elle est loin, très loin d’avoir l’air niais quand elle fait d’endiablés discours éthiques et moraux sur une meilleure société, étudiante en philosophie selon la rumeur, elle a plus de conviction et de charisme, de poids que n’importe quel prêcheur. On lui prête une relation malsaine avec Drasko Vladic néanmoins. Erea est l’impératrice de la dimension astharès sur Gaerras, une des déesses les plus importantes donc et la fille de Nordrar. Elle a hérité de sa mère la maitrise des « vertus » et derrière un sourire angélique cache un caractère inarrêtable. Epouse de Zehol, elle vint sur Terre pour le sauver avant de rester elle￾même. Elle ne veut pas se faire vénérer par le cercle écarlate, mais elle sent qu’une catastrophe pourrait arriver et surveille donc cette faction."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Eliza Freyja"],["Âge apparent","24 ans"],["Nationalité déclarée","Américaine"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Nor vénéré : Enorea"],["Nom de la Réalité","Eliza Freyja"],["Nom de la Vérité","E’nor’rea"],["Âge source","« 24 ans »"],["Affiliations","crawlers : neopunks"],["Nationalité d’origine","Américaine"],["Nature réelle","Astharès"]]},{"type":"p","style":"lore","text":"Rang dans le cercle : Divinité sacrée mais introuvable Eliza est une neopunk qui n’assure pas sa notoriété par un coté destructeur ou antisocial, elle est une neopunk qui vante les qualités et l’égalité de tous les êtres, elle est loin, très loin d’avoir l’air niais quand elle fait d’endiablés discours éthiques et moraux sur une meilleure société, étudiante en philosophie selon la rumeur, elle a plus de conviction et de charisme, de poids que n’importe quel prêcheur. On lui prête une relation malsaine avec Drasko Vladic néanmoins. Erea est l’impératrice de la dimension astharès sur Gaerras, une des déesses les plus importantes donc et la fille de Nordrar. Elle a hérité de sa mère la maitrise des « vertus » et derrière un sourire angélique cache un caractère inarrêtable. Epouse de Zehol, elle vint sur Terre pour le sauver avant de rester elle￾même. Elle ne veut pas se faire vénérer par le cercle écarlate, mais elle sent qu’une catastrophe pourrait arriver et surveille donc cette faction."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-neenthya-glove-49","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Neenthya Glove","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Cercle Écarlate","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Neenthya Glove","real_name_source":"Neenthya Glove","nom_verite":"Nythara","nom_verite_source":"Nythara","race":"Astharès","age":"«25 ans » - ???? ans","origine":"américaine","statut":"","affiliations":"Crawlers : cyberthugs","source_group":"Cercle Écarlate","source_groups":["Cercle Écarlate"],"source_pages":[39],"source_occurrences":1,"source_order":2,"identity_keys":["Neenthya Glove","Nythara","maitre du cercle: Nythara"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"maitre du cercle: Nythara Nom de la Réalité : Neenthya Glove Nom de la Vérité : Nythara Age : «25 ans » - ???? ans Affiliations : Crawlers : cyberthugs Nationalité d’origine : américaine Ethnie réelle : Astharès Rang dans le cercle : Maitresse Neenthya està la tête du gang des « Dead roses », un gang féminin assez sournois versant dans l’arnaque, la prostitution forcée et le chantage. Elles ne sont pas racialisées, ce n’est pas un gang afro-américain exclusivement, asiatiques, mexicaines et autres s’y retrouvent. Elles ne jouent pas un rôle majeur dans les affaires de la pègre ou des crawlers en général, elles sont plus souvent un groupe qu’on appelle en renfort plus qu’un gang auquel on fait appel en premier lieu. Nythara est une descendante de Nyhall, c’est une « princesse démone » en termes de hiérarchie. Elle est une des plus actives quant à la recherche des pouvoirs de Kain et l’activisme pour le libérer. Elle a une haine viscérale pour les vampires mais aussi les angelus qu’elle adore corrompre avec son sceau infernal jusqu’à ce qu’ils ne se désagrègent physiquement à cause de l’incompatibilité des essences. C’est une partisane de la création d’un nouvel être, peu importera le Nor qui en engendra le suivant."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Neenthya Glove"],["Âge apparent","25 ans"],["Nationalité déclarée","américaine"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","maitre du cercle: Nythara"],["Nom de la Réalité","Neenthya Glove"],["Nom de la Vérité","Nythara"],["Âge source","«25 ans » - ???? ans"],["Affiliations","Crawlers : cyberthugs"],["Nationalité d’origine","américaine"],["Nature réelle","Astharès"]]},{"type":"p","style":"lore","text":"Rang dans le cercle : Maitresse Neenthya està la tête du gang des « Dead roses », un gang féminin assez sournois versant dans l’arnaque, la prostitution forcée et le chantage. Elles ne sont pas racialisées, ce n’est pas un gang afro-américain exclusivement, asiatiques, mexicaines et autres s’y retrouvent. Elles ne jouent pas un rôle majeur dans les affaires de la pègre ou des crawlers en général, elles sont plus souvent un groupe qu’on appelle en renfort plus qu’un gang auquel on fait appel en premier lieu. Nythara est une descendante de Nyhall, c’est une « princesse démone » en termes de hiérarchie. Elle est une des plus actives quant à la recherche des pouvoirs de Kain et l’activisme pour le libérer. Elle a une haine viscérale pour les vampires mais aussi les angelus qu’elle adore corrompre avec son sceau infernal jusqu’à ce qu’ils ne se désagrègent physiquement à cause de l’incompatibilité des essences. C’est une partisane de la création d’un nouvel être, peu importera le Nor qui en engendra le suivant."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-rigobertho-arrabal-50","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Rigobertho Arrabal","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Cercle Écarlate","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Rigobertho Arrabal","real_name_source":"Rigobertho Arrabal","nom_verite":"Akharad","nom_verite_source":"Akharad","race":"Asrtharès","age":"«25ans », ????","origine":"mexicain","statut":"","affiliations":"Pègre : cartel Tijuana","source_group":"Cercle Écarlate","source_groups":["Cercle Écarlate"],"source_pages":[40],"source_occurrences":1,"source_order":1,"identity_keys":["Rigobertho Arrabal","Akharad","maitre du cercle: Akharad"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"maitre du cercle: Akharad Nom de la Réalité : Rigobertho Arrabal Nom de la Vérité : Akharad Age : «25ans », ???? Affiliations : Pègre : cartel Tijuana Nationalité d’origine : mexicain Ethnie réelle : Asrtharès Rang dans le cercle : Maitre Rigobertho est un homme aussi séduisant que soumis aux baronnes du cartel de Tijuana. Il est leur jouet régulier, leur amant, leur petite salope, leur homme de ménage également. Loin d’être un simple prostitué dans le cartel, s’il n’a pas de position officielle, c’est le seul homme de confiance de la grande baronne, le voir n’est jamais une si bonne chose étant son messager personnel. A la vie privée, il cherche son amant, Fernando Tenorio, un ancien scientifique du PCRC qui travaillerait pour Ryan Foster, hélas, aucune trace de lui n’est trouvable. Akharad est le plus ancien astharès créé sur Terre. Il était chevalier écarlate de Belial et fut dressé à servir les femmes à cette époque. Il n’a aucun respect pour Kain, et est un activiste farouche pour la création d’une « Mère », une Nor digne des astharès terrestres. Pour lui, il faut que Belial soit celle dotée du corps de Nor. C’est un partisan des daemons, il a une haine profonde pour les Angelus."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Rigobertho Arrabal"],["Âge apparent","25ans"],["Nationalité déclarée","mexicain"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","maitre du cercle: Akharad"],["Nom de la Réalité","Rigobertho Arrabal"],["Nom de la Vérité","Akharad"],["Âge source","«25ans », ????"],["Affiliations","Pègre : cartel Tijuana"],["Nationalité d’origine","mexicain"],["Nature réelle","Asrtharès"]]},{"type":"p","style":"lore","text":"Rang dans le cercle : Maitre Rigobertho est un homme aussi séduisant que soumis aux baronnes du cartel de Tijuana. Il est leur jouet régulier, leur amant, leur petite salope, leur homme de ménage également. Loin d’être un simple prostitué dans le cartel, s’il n’a pas de position officielle, c’est le seul homme de confiance de la grande baronne, le voir n’est jamais une si bonne chose étant son messager personnel. A la vie privée, il cherche son amant, Fernando Tenorio, un ancien scientifique du PCRC qui travaillerait pour Ryan Foster, hélas, aucune trace de lui n’est trouvable. Akharad est le plus ancien astharès créé sur Terre. Il était chevalier écarlate de Belial et fut dressé à servir les femmes à cette époque. Il n’a aucun respect pour Kain, et est un activiste farouche pour la création d’une « Mère », une Nor digne des astharès terrestres. Pour lui, il faut que Belial soit celle dotée du corps de Nor. C’est un partisan des daemons, il a une haine profonde pour les Angelus."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-zoey-hole-51","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Zoey Hole","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Cercle Écarlate","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Zoey Hole","real_name_source":"Zoey Hole","nom_verite":"Zehol’Zaalziel","nom_verite_source":"Zehol’Zaalziel","race":"Asrtharès","age":"«29 ans » - ???? ans","origine":"américaine","statut":"","affiliations":"Crawlers : fixers","source_group":"Cercle Écarlate","source_groups":["Cercle Écarlate"],"source_pages":[40],"source_occurrences":1,"source_order":2,"identity_keys":["Zoey Hole","Zehol’Zaalziel","Maitre du cercle : Zehol"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Maitre du cercle : Zehol Nom de la Réalité : Zoey Hole Nom de la Vérité : Zehol’Zaalziel Age : «29 ans » - ???? ans Affiliations : Crawlers : fixers Nationalité d’origine : américaine Ethnie réelle : Asrtharès Rang dans le cercle : Maitresse Zoey Hole est la maitresse du bar neopunk « Aphokalips». Avec son regard extrêmement vicieux, son air pervers et ses milliers de sous-entendus sexuels, c’est une femme assez dérangeante, car elle a la fâcheuse tendance à coller de très prêts les nouveaux dans son bar. Meilleure amie de Daniela Göetz, c’est elle qui la soigna après son évasion des chevaliers des saintes lagunes. Zoey est aussi »morphosexuelle » selon ses dires, elle parle souvent de son pénis aux gens qui lui plaisent. Maitresse du cercle écarlate, elle se présente comme étant en vérité « Zehol » l’archidémon des poisons et de la tromperie. Elle laisse courir la rumeur comme quoi elle serait plutôt sa fille avec Erea chez ceux se refusant à croire que c’est bien l’Archidémon détestable. La vérité est qu’elle est probablement une descendante de Zehol ayant oublié son propre prénom tant elle s’accroche à semer le doute. Elle n’est pas un homme ni même capable de se morpher anatomiquement, c’est une mythomane invétérée. C’est une partisane des angelus, malgré le massacre, elle estime qu’Elynea a sauvé les Astharès de R’Gahanath. Elle trompe Daniela et les vampires mais les méprisent au plus haut point."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Zoey Hole"],["Âge apparent","29 ans"],["Nationalité déclarée","américaine"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Maitre du cercle : Zehol"],["Nom de la Réalité","Zoey Hole"],["Nom de la Vérité","Zehol’Zaalziel"],["Âge source","«29 ans » - ???? ans"],["Affiliations","Crawlers : fixers"],["Nationalité d’origine","américaine"],["Nature réelle","Asrtharès"]]},{"type":"p","style":"lore","text":"Rang dans le cercle : Maitresse Zoey Hole est la maitresse du bar neopunk « Aphokalips». Avec son regard extrêmement vicieux, son air pervers et ses milliers de sous-entendus sexuels, c’est une femme assez dérangeante, car elle a la fâcheuse tendance à coller de très prêts les nouveaux dans son bar. Meilleure amie de Daniela Göetz, c’est elle qui la soigna après son évasion des chevaliers des saintes lagunes. Zoey est aussi »morphosexuelle » selon ses dires, elle parle souvent de son pénis aux gens qui lui plaisent. Maitresse du cercle écarlate, elle se présente comme étant en vérité « Zehol » l’archidémon des poisons et de la tromperie. Elle laisse courir la rumeur comme quoi elle serait plutôt sa fille avec Erea chez ceux se refusant à croire que c’est bien l’Archidémon détestable. La vérité est qu’elle est probablement une descendante de Zehol ayant oublié son propre prénom tant elle s’accroche à semer le doute. Elle n’est pas un homme ni même capable de se morpher anatomiquement, c’est une mythomane invétérée. C’est une partisane des angelus, malgré le massacre, elle estime qu’Elynea a sauvé les Astharès de R’Gahanath. Elle trompe Daniela et les vampires mais les méprisent au plus haut point."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-nattalia-rizkina-52","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Nattalia Rizkina","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Autres factions","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Nattalia Rizkina","real_name_source":"Nattalia Rizkina","nom_verite":"Araley Praelyan","nom_verite_source":"Araley Praelyan","race":"Azménorienne","age":"« 24 ans »","origine":"Américaine","statut":"Seigneur des Servants","affiliations":"Corporatif : Byron industries","source_group":"Autres factions","source_groups":["Autres factions"],"source_pages":[42],"source_occurrences":1,"source_order":1,"identity_keys":["Nattalia Rizkina","Araley Praelyan","Les servants de Pluton : Araley Praelyan"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Les servants de Pluton : Araley Praelyan Nom de la Réalité : Nattalia Rizkina Nom de la Vérité : Araley Praelyan Age : « 24 ans » Affiliations : Corporatif : Byron industries Nationalité d’origine : Américaine Ethnie réelle : Azménorienne Rang : Seigneur des Servants Nattalia Rizkina est la directrice de la sous-branche « offensive » de l’armement à Byron industries. Riche héritière, elle aurait pu se lancer dans une corporation elle-même mais Melina Byron l’intimida bien trop. Femme impressionnable quoi qu’intelligente, elle apparait un peu niaise et futile dans un premier temps, elle parle beaucoup de son mari et de ses projets de vie, laissant clairement parfois entendre une naïveté écœurante pour 2035 que seule une bourgeoise privilégiée comme elle peut oser avoir. Pourtant ce serait clairement tomber dans son jeu, en effet, elle semble avoir une personnalité bien plus affirmée qu’elle ne laisse paraitre quand il faut se décider. C’est moins étonnant quand on sait qu’elle est la principale tête pensante de sa faction. Certains supposent même qu’elle descendrait de Kaless Proleyh mais personne n’ose le dire. Elle négocie souvent avec Rached Kelley (empereur rocréen) de la Raven et Samantha Malanwe ( du conseil des Anciens), En vérité c’est une monstrueuse manipulatrice."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Nattalia Rizkina"],["Âge apparent","24 ans"],["Nationalité déclarée","Américaine"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Les servants de Pluton : Araley Praelyan"],["Nom de la Réalité","Nattalia Rizkina"],["Nom de la Vérité","Araley Praelyan"],["Âge source","« 24 ans »"],["Affiliations","Corporatif : Byron industries"],["Nationalité d’origine","Américaine"],["Nature réelle","Azménorienne"],["Rang","Seigneur des Servants"]]},{"type":"p","style":"lore","text":"Nattalia Rizkina est la directrice de la sous-branche « offensive » de l’armement à Byron industries. Riche héritière, elle aurait pu se lancer dans une corporation elle-même mais Melina Byron l’intimida bien trop. Femme impressionnable quoi qu’intelligente, elle apparait un peu niaise et futile dans un premier temps, elle parle beaucoup de son mari et de ses projets de vie, laissant clairement parfois entendre une naïveté écœurante pour 2035 que seule une bourgeoise privilégiée comme elle peut oser avoir. Pourtant ce serait clairement tomber dans son jeu, en effet, elle semble avoir une personnalité bien plus affirmée qu’elle ne laisse paraitre quand il faut se décider. C’est moins étonnant quand on sait qu’elle est la principale tête pensante de sa faction. Certains supposent même qu’elle descendrait de Kaless Proleyh mais personne n’ose le dire. Elle négocie souvent avec Rached Kelley (empereur rocréen) de la Raven et Samantha Malanwe ( du conseil des Anciens), En vérité c’est une monstrueuse manipulatrice."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-jack-steven-53","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Jack Steven","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Autres factions","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Jack Steven","real_name_source":"Jack Steven","nom_verite":"","nom_verite_source":"?","race":"Azménorienne","age":"«40 ans »","origine":"britannique","statut":"Seigneur des Lueurs","affiliations":"crawlers : voidrunners / chasseurs","source_group":"Autres factions","source_groups":["Autres factions"],"source_pages":[42],"source_occurrences":1,"source_order":2,"identity_keys":["Jack Steven","Lueurs d’Azménor : Jack Steven"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Lueurs d’Azménor : Jack Steven Nom de la Réalité : Jack Steven Nom de la Vérité : ? Age : «40 ans » Affiliations : crawlers : voidrunners / chasseurs Nationalité d’origine : britannique Ethnie réelle : Azménorienne Rang : Seigneur des Lueurs Jack Steven est un crawler et un chasseur de l’Association. Il est toutefois très bas dans les listes, ce n’est pas un des chasseurs les plus craints ni un assassin des plus demandés par la Blanchisserie. La raison est qu’il est très discret, appartenant à la secte des Lueurs d’Azménor, qu’il dirige au demeurant, c’est le « grand devin », qui reçoit des visions des « Menaces », un concept regroupant les voyageurs, les Mages, les fléaux et abominations, les cultes secrets et toute forme de pouvoir surnaturel que la secte va rejeter. L’ancêtre de Jack est glorifié mais tenu anonyme, il aurait rassemblé des prêtres et des paladins, des chevaliers d’Aèr afin de lutter contre une menace. L’ironique vérité c’est que son ancêtre prit les armes pour Elynea à l’époque, mais son groupe de preux ne fut pas transcendé, il fut sacrifié. Toutefois, les survivants interprétèrent mal leur destin et le fils du paladin entendit des voix l’aider à survivre. Ces voix venaient d’une créature issue du Néant et dota l’ordre de quelques dons. S’ils sont d’incroyables chasseurs de surnaturel, ces « chevaliers azménoriens » sont enfermés dans de nombreux mensonges et croyances difformes d’une réalité malsaine."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Jack Steven"],["Âge apparent","40 ans"],["Nationalité déclarée","britannique"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Lueurs d’Azménor : Jack Steven"],["Nom de la Réalité","Jack Steven"],["Nom de la Vérité","?"],["Âge source","«40 ans »"],["Affiliations","crawlers : voidrunners / chasseurs"],["Nationalité d’origine","britannique"],["Nature réelle","Azménorienne"],["Rang","Seigneur des Lueurs"]]},{"type":"p","style":"lore","text":"Jack Steven est un crawler et un chasseur de l’Association. Il est toutefois très bas dans les listes, ce n’est pas un des chasseurs les plus craints ni un assassin des plus demandés par la Blanchisserie. La raison est qu’il est très discret, appartenant à la secte des Lueurs d’Azménor, qu’il dirige au demeurant, c’est le « grand devin », qui reçoit des visions des « Menaces », un concept regroupant les voyageurs, les Mages, les fléaux et abominations, les cultes secrets et toute forme de pouvoir surnaturel que la secte va rejeter. L’ancêtre de Jack est glorifié mais tenu anonyme, il aurait rassemblé des prêtres et des paladins, des chevaliers d’Aèr afin de lutter contre une menace. L’ironique vérité c’est que son ancêtre prit les armes pour Elynea à l’époque, mais son groupe de preux ne fut pas transcendé, il fut sacrifié. Toutefois, les survivants interprétèrent mal leur destin et le fils du paladin entendit des voix l’aider à survivre. Ces voix venaient d’une créature issue du Néant et dota l’ordre de quelques dons. S’ils sont d’incroyables chasseurs de surnaturel, ces « chevaliers azménoriens » sont enfermés dans de nombreux mensonges et croyances difformes d’une réalité malsaine."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-kathy-hill-54","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Kathy Hill","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Autres factions","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Kathy Hill","real_name_source":"Kathy Hill","nom_verite":"Kethyll","nom_verite_source":"Kethyll","race":"Driwlienne","age":"«34 ans »","origine":"inconnue","statut":"Pseudo-humaine/ archiprêtresse tishane","affiliations":"Crawlers : insurgés/ pègre/religieux","source_group":"Autres factions","source_groups":["Autres factions"],"source_pages":[43],"source_occurrences":1,"source_order":1,"identity_keys":["Kathy Hill","Kethyll","Nouvelle Eglise Tishane : Kethyll"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Nouvelle Eglise Tishane : Kethyll Nom de la Réalité : Kathy Hill Nom de la Vérité : Kethyll Age : «34 ans » Affiliations : Crawlers : insurgés/ pègre/religieux Nationalité d’origine : inconnue Ethnie réelle : Driwlienne Statut : Pseudo-humaine/ archiprêtresse tishane Kathy est une insurgée un peu atypique, on ne sait rien d’elle, son logifate est absolument négatif alors que c’est une personne charmante et avenante, elle a établi en quelques années, si ce n’est en quelques mois un réseau monstrueux de trafic d’organes et autres biogmentations. Elle est imprévisible et on ne sait absolument jamais qui est à son service, sur l’holonet, la secte tishane fait aussi des adeptes et elle a été approchée par l’ordre de Longinus qu’elle aurait intégré. Fille de la déesse Echidna sur Gaerras seconde, c’est une « pseudohumaine » liée aux gobelins, les pseudo-humains sont des divinités mineures des « monstres » de Gaerras, possédant une forme humaine, une forme monstrueuse et une forme éveillée mais surtout qui servent de point de relais magique entre la déesse majeur et une espèce de monstre. Kethyll est une Pseudo-humaine redondante, elle n’est pas la véritable mère des Groeln (les gobelins) mais peut en créer. Sur Gaerras, après avoir frôlé la folie à la suite de massacres sur les monstres, elle s’est échappée sur Terre où elle créa sa propre forme de Groeln pour en devenir l’impératrice et fuir ce qui massacra les siens à tout jamais. Elle a fondé un nouveau culte de la « Bagatisha » une croyance des groeln."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Kathy Hill"],["Âge apparent","34 ans"],["Nationalité déclarée","inconnue"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Nouvelle Eglise Tishane : Kethyll"],["Nom de la Réalité","Kathy Hill"],["Nom de la Vérité","Kethyll"],["Âge source","«34 ans »"],["Affiliations","Crawlers : insurgés/ pègre/religieux"],["Nationalité d’origine","inconnue"],["Nature réelle","Driwlienne"],["Statut","Pseudo-humaine/ archiprêtresse tishane"]]},{"type":"p","style":"lore","text":"Kathy est une insurgée un peu atypique, on ne sait rien d’elle, son logifate est absolument négatif alors que c’est une personne charmante et avenante, elle a établi en quelques années, si ce n’est en quelques mois un réseau monstrueux de trafic d’organes et autres biogmentations. Elle est imprévisible et on ne sait absolument jamais qui est à son service, sur l’holonet, la secte tishane fait aussi des adeptes et elle a été approchée par l’ordre de Longinus qu’elle aurait intégré. Fille de la déesse Echidna sur Gaerras seconde, c’est une « pseudohumaine » liée aux gobelins, les pseudo-humains sont des divinités mineures des « monstres » de Gaerras, possédant une forme humaine, une forme monstrueuse et une forme éveillée mais surtout qui servent de point de relais magique entre la déesse majeur et une espèce de monstre. Kethyll est une Pseudo-humaine redondante, elle n’est pas la véritable mère des Groeln (les gobelins) mais peut en créer. Sur Gaerras, après avoir frôlé la folie à la suite de massacres sur les monstres, elle s’est échappée sur Terre où elle créa sa propre forme de Groeln pour en devenir l’impératrice et fuir ce qui massacra les siens à tout jamais. Elle a fondé un nouveau culte de la « Bagatisha » une croyance des groeln."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-connor-cherros-55","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Connor Cherros","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Autres factions","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Connor Cherros","real_name_source":"Connor Cherros","nom_verite":"Koldraal’Sheroh","nom_verite_source":"Koldraal’Sheroh","race":"Dalkeith corrompus","age":"«51ans » - ???? ans","origine":"américaine","statut":"Empereur","affiliations":"corporation : Armée d’Andrea","source_group":"Autres factions","source_groups":["Autres factions"],"source_pages":[43],"source_occurrences":1,"source_order":2,"identity_keys":["Connor Cherros","Koldraal’Sheroh","Autre : Koldraal’Sheroh"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Autre : Koldraal’Sheroh Nom de la Réalité : Connor Cherros Nom de la Vérité : Koldraal’Sheroh Age : «51ans » - ???? ans Affiliations : corporation : Armée d’Andrea Nationalité d’origine : américaine Ethnie réelle : Dalkeith corrompus Titre : Empereur Connor est le bras droit d’Andrea Shield. Il était un ancien de la Black Crow et a fait plusieurs guerres en tant que mercenaire aussi bien que militaire régulier. Absolument taciturne et glacial, c’est un tacticien difficile à égaler malgré ses allures de brute épaisse. Sur Inryase, un monde magique, durant l’âge des « Brumes », il a unifié les tribus des « démons élémentaires » sous un seul empire et abattu des dragons pour utiliser leur sang en quantité. Conquérant sanguinaire ou génie unificateur, la vérité n’est pas un compromis des deux visions, il a été tout cela à la fois. Vaincu finalement, par un fléau, son héritage ne dura pas tant que ça, quelques millénaires avant la destruction d’Inryase. Corrompu par le fléau Sheroh, qu’il finit par dévorer et assimiler, il erra jusqu’à arriver sur le monde d’Elweoth où il rencontra Morrighan, qui en fit un loyal allié, lui promettant de trouver quelqu’un pour le soigner de la corruption. Absolument loyal et redevable à Morrighan, il la suivit sur Terre et y demeura. S’il a la puissance d’un Fléau encore, il peut égaler une divinité et c’est pour ça qu’il est scellé. Tous les survivants d’Inryase viennent à lui instinctivement, seule chance qu’il ne tue la déesse monde d’Inryase afin de recréer leur planète."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Connor Cherros"],["Âge apparent","51ans"],["Nationalité déclarée","américaine"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Autre : Koldraal’Sheroh"],["Nom de la Réalité","Connor Cherros"],["Nom de la Vérité","Koldraal’Sheroh"],["Âge source","«51ans » - ???? ans"],["Affiliations","corporation : Armée d’Andrea"],["Nationalité d’origine","américaine"],["Nature réelle","Dalkeith corrompus"],["Titre","Empereur"]]},{"type":"p","style":"lore","text":"Connor est le bras droit d’Andrea Shield. Il était un ancien de la Black Crow et a fait plusieurs guerres en tant que mercenaire aussi bien que militaire régulier. Absolument taciturne et glacial, c’est un tacticien difficile à égaler malgré ses allures de brute épaisse. Sur Inryase, un monde magique, durant l’âge des « Brumes », il a unifié les tribus des « démons élémentaires » sous un seul empire et abattu des dragons pour utiliser leur sang en quantité. Conquérant sanguinaire ou génie unificateur, la vérité n’est pas un compromis des deux visions, il a été tout cela à la fois. Vaincu finalement, par un fléau, son héritage ne dura pas tant que ça, quelques millénaires avant la destruction d’Inryase. Corrompu par le fléau Sheroh, qu’il finit par dévorer et assimiler, il erra jusqu’à arriver sur le monde d’Elweoth où il rencontra Morrighan, qui en fit un loyal allié, lui promettant de trouver quelqu’un pour le soigner de la corruption. Absolument loyal et redevable à Morrighan, il la suivit sur Terre et y demeura. S’il a la puissance d’un Fléau encore, il peut égaler une divinité et c’est pour ça qu’il est scellé. Tous les survivants d’Inryase viennent à lui instinctivement, seule chance qu’il ne tue la déesse monde d’Inryase afin de recréer leur planète."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]}] as Array<Record<string, any>>;
export default PAYLOAD;
